import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        if (s.startsWith("dot") || s.startsWith("at") || s.endsWith("at") || s.endsWith("dot")) {
            if (s.startsWith("dot")) {
                String t = s.substring(3);
                String[] a = t.split("dot");
                String l = String.join(".", a);
                int b = l.indexOf("at");
                String o = l.substring(0, b) + "@" + l.substring(b + 2);
                String q = "dot" + o;
                if (q.endsWith(".")) {
                    String aStr = q.substring(0, q.length() - 1);
                    s = aStr + "dot";
                } else if (q.endsWith("@")) {
                    String aStr = q.substring(0, q.length() - 1);
                    s = aStr + "at";
                } else {
                    s = q;
                }
            }

            if (s.startsWith("at")) {
                String t = s.substring(2);
                String[] a = t.split("dot");
                String l = String.join(".", a);
                int b = l.indexOf("at");
                String o = l.substring(0, b) + "@" + l.substring(b + 2);
                String q = "at" + o;
                if (q.endsWith(".")) {
                    String aStr = q.substring(0, q.length() - 1);
                    s = aStr + "dot";
                } else if (q.endsWith("@")) {
                    String aStr = q.substring(0, q.length() - 1);
