                String l = String.join(".", a);
                int b = l.indexOf("at");
                String q = l.substring(0, b) + "@" + l.substring(b + 2);
                s = q + "dot";
            }

            if (s.length() >= 2 && s.endsWith("at") && !s.startsWith("dot") && !s.startsWith("at")) {
                String t = s.substring(0, s.length() - 2);
                String[] a = t.split("dot");
                String l = String.join(".", a);
                int b = l.indexOf("at");
                String q = l.substring(0, b) + "@" + l.substring(b + 2);
                s = q + "at";
            }

            System.out.println(s);
        } else {
            String[] a = s.split("dot");
            String l = String.join(".", a);
            int b = l.indexOf("at");
            String q = l.substring(0, b) + "@" + l.substring(b + 2);
            System.out.println(q);
        }
        scanner.close();
    }
}
